{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "RegionalMetricsDataset",
  "description": "Normalized regional metrics dataset partitioned by reporting district (north, south, west).",
  "type": "object",
  "required": [
    "north",
    "south",
    "west"
  ],
  "additionalProperties": false,
  "properties": {
    "north": {
      "type": "array",
      "description": "Records from Northern district retail and enterprise terminals.",
      "items": {
        "$ref": "#/$defs/MetricRecord"
      }
    },
    "south": {
      "type": "array",
      "description": "Records from Southern district partner and franchise outlets.",
      "items": {
        "$ref": "#/$defs/MetricRecord"
      }
    },
    "west": {
      "type": "array",
      "description": "Records from Western district distribution centers and online fulfillment.",
      "items": {
        "$ref": "#/$defs/MetricRecord"
      }
    }
  },
  "$defs": {
    "MetricRecord": {
      "type": "object",
      "required": [
        "gross",
        "refunds",
        "cost"
      ],
      "additionalProperties": false,
      "properties": {
        "gross": {
          "type": [
            "integer",
            "null"
          ],
          "description": "Gross receipts in integer currency units. Null indicates missing or unrecorded input."
        },
        "refunds": {
          "type": [
            "integer",
            "null"
          ],
          "description": "Customer refunds in integer currency units. Null indicates missing or unrecorded input."
        },
        "cost": {
          "type": [
            "integer",
            "null"
          ],
          "description": "Direct fulfillment and delivery cost in integer currency units. Null indicates missing or unrecorded input."
        }
      }
    }
  }
}

