import json, sys, pathlib

records_path = pathlib.Path("records.json")
if not records_path.exists():
    print("Validation failed: records.json does not exist.", file=sys.stderr)
    sys.exit(1)

try:
    data = json.loads(records_path.read_text(encoding="utf8"))
except Exception as e:
    print(f"Validation failed: records.json is not valid JSON: {e}", file=sys.stderr)
    sys.exit(1)

if not isinstance(data, dict):
    print("Validation failed: root must be a JSON object.", file=sys.stderr)
    sys.exit(1)

expected = {}
for region in ["north", "south", "west"]:
    feed_path = pathlib.Path(f"inputs/{region}.json")
    if not feed_path.exists():
        print(f"Validation failed: raw feed {feed_path} missing.", file=sys.stderr)
        sys.exit(1)
    try:
        raw_feed = json.loads(feed_path.read_text(encoding="utf8"))
    except Exception as e:
        print(f"Validation failed: {feed_path} invalid JSON: {e}", file=sys.stderr)
        sys.exit(1)
    if not isinstance(raw_feed, list):
        print(f"Validation failed: {feed_path} must be a list of transactions.", file=sys.stderr)
        sys.exit(1)
    expected[region] = [
        {"gross": r["gross"], "refunds": r["refunds"], "cost": r["cost"]}
        for r in raw_feed if isinstance(r, dict) and r.get("status") == "cleared"
    ]

for region in ["north", "south", "west"]:
    if region not in data:
        print(f"Validation failed: missing region '{region}' in records.json.", file=sys.stderr)
        sys.exit(1)
    actual_records = data[region]
    if not isinstance(actual_records, list):
        print(f"Validation failed: region '{region}' must be a list.", file=sys.stderr)
        sys.exit(1)
    if len(actual_records) != len(expected[region]):
        print(f"Validation failed: region '{region}' count mismatch (expected {len(expected[region])}, got {len(actual_records)}).", file=sys.stderr)
        sys.exit(1)
    for idx, (act, exp) in enumerate(zip(actual_records, expected[region])):
        if act != exp:
            print(f"Validation failed: {region}[{idx}] mismatch: expected {exp}, got {act}.", file=sys.stderr)
            sys.exit(1)
    print(f"Region '{region}': {len(actual_records)} cleared records verified against inputs/{region}.json.")

extra_regions = [r for r in data if r not in ["north", "south", "west"]]
if extra_regions:
    print(f"Validation failed: unexpected regions in records.json: {extra_regions}.", file=sys.stderr)
    sys.exit(1)

total = sum(len(expected[r]) for r in expected)
print(f"Validation succeeded: {total} total cleared records from regional inputs verified in records.json.")

